    if(inside){const detail=e.closest?.('[data-view-key]');s.focus=e.id?{id:e.id,start:e.selectionStart,end:e.selectionEnd,direction:e.selectionDirection}:detail?{viewKey:detail.dataset.viewKey}:null}
    else s.focus=null;
